SELECT m.id, m.symbol, m.observed_at, m.created_at, ROUND(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at)/1000) AS ingest_lag_ms, m.price, m.delivery_status, m.outcome_reason FROM crypto_ai.market_price_event m WHERE (m.symbol='EGLDUSDT' AND m.observed_at BETWEEN '2026-10-11 20:59:55' AND '2026-10-11 21:00:15') OR (m.symbol='EGLDUSDT' AND m.observed_at BETWEEN '2026-10-11 22:42:55' AND '2026-10-11 22:44:00') OR (m.symbol='XRPUSDT' AND m.observed_at BETWEEN '2026-10-12 03:29:55' AND '2026-10-12 03:30:10') OR (m.symbol='DOGEUSDT' AND m.observed_at BETWEEN '2026-10-12 04:25:55' AND '2026-10-12 04:26:10') OR (m.symbol='SHIBUSDT' AND m.observed_at BETWEEN '2026-10-12 07:14:55' AND '2026-10-12 07:15:50') OR (m.symbol='ACEUSDT' AND m.observed_at BETWEEN '2026-10-12 10:04:55' AND '2026-10-12 10:05:25') ORDER BY m.symbol, m.observed_at LIMIT 200